UPDATE products p SET
 sku=source.sku,game_category=source.game_category,tier='SERVICE',name=source.name,
 description=source.description,fulfillment_type=source.fulfillment_type,
 sale_price_xtr=1,cost_price_xtr=0,status='PENDING_REVIEW',is_test=FALSE,
 current_rights_review_id=NULL,marketplace_category_id=(SELECT id FROM marketplace_categories WHERE slug=source.category_slug),
 customer_terms=source.customer_terms,fulfillment_eta='',
 attributes=jsonb_build_object('subkategori',source.subcategory,'metode_penyerahan',source.delivery_method,'price_min_idr',source.price_min::text,'price_max_idr',source.price_max::text,'price_currency','IDR','price_note','Rentang harga dari file Owner; harga checkout XTR belum ditetapkan.'),
 updated_at=NOW()
FROM source WHERE p.sku=source.old_sku AND source.old_sku<>'';

