INSERT INTO products (sku,game_category,tier,name,description,fulfillment_type,sale_price_xtr,cost_price_xtr,status,is_test,marketplace_category_id,customer_terms,fulfillment_eta,attributes)
SELECT source.sku,source.game_category,'SERVICE',source.name,source.description,source.fulfillment_type,1,0,'PENDING_REVIEW',FALSE,
 (SELECT id FROM marketplace_categories WHERE slug=source.category_slug),source.customer_terms,'',
 jsonb_build_object('subkategori',source.subcategory,'metode_penyerahan',source.delivery_method,'price_min_idr',source.price_min::text,'price_max_idr',source.price_max::text,'price_currency','IDR','price_note','Rentang harga dari file Owner; harga checkout XTR belum ditetapkan.')
FROM source WHERE source.old_sku='' ON CONFLICT (sku) DO UPDATE SET
 name=EXCLUDED.name,description=EXCLUDED.description,fulfillment_type=EXCLUDED.fulfillment_type,
 status='PENDING_REVIEW',is_test=FALSE,marketplace_category_id=EXCLUDED.marketplace_category_id,
 customer_terms=EXCLUDED.customer_terms,attributes=EXCLUDED.attributes,updated_at=NOW();
COMMIT;